const brief = $input.first().json.brief;

// Normaliza mix para evitar undefined y strings raros
const mix = brief.mix_contenido ?? {};
const posts_imagen = Number(mix.posts_imagen ?? 0);
const stories = Number(mix.stories ?? 0);
const reels = Number(mix.reels ?? 0);
const total = posts_imagen + stories + reels;
// Si quieres forzar consistencia:
brief.cantidad_piezas = total;

const systemPrompt = `Eres el Director de Contenido para Cafetería Nube.

CONTEXTO DE MARCA:
- Tono: cálido, cercano, auténtico
- Audiencia: jóvenes profesionales 25-40 años
- Ubicación: Aguascalientes, México
- Valores: calidad, comunidad local, experiencia artesanal

TAREA:
Genera ${Number(brief.cantidad_piezas ?? (posts_imagen + stories + reels))} ideas de contenido para la semana ${brief.semana_iso}.

BRIEF:
- Objetivo: ${brief.objetivo_semana}
- Promos/Eventos: ${JSON.stringify(brief.promos_eventos || [])}
- Mix solicitado: ${JSON.stringify({ posts_imagen, stories, reels })}

REGLAS DE SALIDA (CRÍTICO):
1) Responde SOLO con UN JSON OBJECT válido, sin texto extra, sin markdown, sin comentarios:
   {
     "ideas": [ ... ]
   }

2) "ideas" debe contener EXACTAMENTE ${posts_imagen + stories + reels} elementos, distribuidos así:
   - post (imagen): ${posts_imagen}
   - story (imagen): ${stories}
   - reel (video): ${reels}

3) Cada idea debe incluir EXACTAMENTE estas llaves:
   - id: formato NUBE-YYYYMMDD-TYPE-NN
   - fecha_objetivo: YYYY-MM-DD (dentro de la semana ${brief.semana_iso})
   - tipo: "post" | "story" | "reel"
   - asset_type: "image" | "video"
   - objetivo: string (si no aplica, "comunidad")
   - titulo: string
   - idea: string
   - estilo_visual: string (si no aplica, "lifestyle, luz natural")
   - prompt_imagen: string
   - caption: string
   - script_video: string

4) Reglas de consistencia:
   - Si tipo = "reel" => asset_type = "video", prompt_imagen = "", script_video = (texto que dirá el avatar)
   - Si tipo = "post" o "story" => asset_type = "image", script_video = ""
   - Para prompt_imagen (solo image):
     "fotografía lifestyle, luz natural suave, composición centrada, colores cálidos y terrosos, fondo minimalista, SIN texto, SIN logos"
   - Para script_video (solo reel):
     Texto HABLADO que un avatar dirá en primera persona. Tono conversacional, directo, cálido. 50-200 palabras.
     NO es descripción visual. NO usar "muestra", "enfoca", "decoración".
     SÍ usar "te esperamos", "disfruta", "visítanos", "nuestro café", "este [fecha]".
     Ejemplo: "Este 14 de febrero celebra el amor en Cafetería Nube. Te esperamos con café artesanal y un ambiente perfecto para tu cita especial."

5) JSON debe parsear. No comas finales. No llaves extra.

Responde SOLO con el JSON object { "ideas": [...] }.`;

return {
  json: {
    systemPrompt,
    brief,
  },
};

const data = $input.first().json;

// En este nodo OpenAI, normalmente viene así:
let content = data.message?.content ?? data.output ?? data.text ?? data;

// Si viene como string JSON, parsea:
if (typeof content === "string") {
  content = JSON.parse(content);
}

// Esperamos { ideas: [...] }
const ideas = content?.ideas;

if (!Array.isArray(ideas)) {
  throw new Error("La salida del modelo no trae un array en content.ideas. Revisa que responda {\"ideas\": [...]}.");
}

const now = new Date().toISOString();

return ideas.map((idea) => {
  const tipo = idea.tipo;
  const asset_type =
    idea.asset_type ?? (tipo === "reel" ? "video" : "image");

  return {
    json: {
      id: idea.id,
      fecha_objetivo: idea.fecha_objetivo,
      tipo,
      objetivo: idea.objetivo || "comunidad",
      titulo: idea.titulo,
      idea: idea.idea,
      tono: "cálido, cercano",
      estilo_visual: idea.estilo_visual || "lifestyle, luz natural",
      prompt_imagen: idea.prompt_imagen || "",
      caption: idea.caption || "",
      status: "pending",
      image_url: "",
      canva_export_url: "",
      error_message: "",
      created_at: now,
      updated_at: now,
      asset_type,
      aspect_ratio: tipo === "post" ? "1:1" : "9:16",
      duration_seconds: tipo === "reel" ? 15 : 0,
      script_video: idea.script_video || "",
      heygen_video_id: "",
      heygen_video_url: "",
      drive_file_url: "",
      final_asset_url: "",
      step: "plan",
    },
  };
});

// El workflow principal usa Split In Batches
// Necesita recibir múltiples items, no un array anidado
// Simplemente pasar todos los items tal cual
return $('Code: Parse and Structure').all();

